```javascript
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, PointLight } = THREE;

  const group = new Group();
  const timelines = [];
  let scrollSettleTimer;

  // === CONSTANTS ===
  const PLATE_W = 1.9;
  const PLATE_H = 1.2;
  const PITCH = 1.5;
  const COL_X = 0.9;
  const N_PLATES = 6;
  const LOOP_H = N_PLATES * PITCH; // 9.0
  const BEVEL_W = 0.03;
  const ACCENT_W = 0.03;

  // Colors from spec
  const COLORS = {
    bg: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38
  };

  const CAPTIONS = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  // === STATE ===
  const state = {
    columnY: 0,
    velocity: 0,
    isSettling: false
  };

  const plateMeshes = [];
  const captionMeshes = [];
  let baseTexture = null;
  let accentLight = null;

  // === LOAD TEXTURE ===
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    baseTexture = tex;
    plateMeshes.forEach((m) => {
      m.material.map = tex;
      m.material.needsUpdate = true;
    });
  });

  // === CREATE PLATES & BEVELS ===
  for (let i = 0; i < N_PLATES; i++) {
    const plateY = -i * PITCH;

    // Plate quad
    const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const plateMat = new MeshPhysicalNodeMaterial({
      color: COLORS.paper,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      toneMapped: true
    });

    const plateMesh = new Mesh(plateGeo, plateMat);
    plateMesh.position.set(COL_X, plateY, 0);
    plateMesh.userData.plateIdx = i;
    plateMeshes.push(plateMesh);
    group.add(plateMesh);

    // Bevel frame (4 bars around plate)
    const bevMat = new MeshPhysicalNodeMaterial({
      color: COLORS.ink,
      roughness: 0.5,
      metalness: 0.5,
      toneMapped: true
    });

    // Top bar
    const topGeo = new PlaneGeometry(PLATE_W + BEVEL_W * 2, BEVEL_W);
    const topMesh = new Mesh(topGeo, bevMat.clone());
    topMesh.position.set(COL_X, plateY + PLATE_H / 2 + BEVEL_W / 2, 0.001);
    group.add(topMesh);

    // Bottom bar
    const botGeo = new PlaneGeometry(PLATE_W + BEVEL_W * 2, BEVEL_W);
    const botMesh = new Mesh(botGeo, bevMat.clone());
    botMesh.position.set(COL_X, plateY - PLATE_H / 2 - BEVEL_W / 2, 0.001);
    group.add(botMesh);

    // Left bar
    const leftGeo = new PlaneGeometry(BEVEL_W, PLATE_H);
    const leftMesh = new Mesh(leftGeo, bevMat.clone());
    leftMesh.position.set(COL_X - PLATE_W / 2 - BEVEL_W / 2, plateY, 0.001);
    group.add(leftMesh);

    // Right bar
    const rightGeo = new PlaneGeometry(BEVEL_W, PLATE_H);
    const rightMesh = new Mesh(rightGeo, bevMat.clone());
    rightMesh.position.set(COL_X + PLATE_W / 2 + BEVEL_W / 2, plateY, 0.001);
    group.add(rightMesh);
  }

  // === CREATE CAPTIONS ===
  for (let i = 0; i < N_PLATES; i++) {
    const capText = ctx.fontAtlas.createText(CAPTIONS[i], {
      fontSize: 18,
      color: COLORS.paper,
      align: 'left',
      letterSpacingPx: 0.08 * 18
    });
    capText.position.set(-1.6, -i * PITCH + 0.2, 0.1);
    capText.userData.plateIdx = i;
    capText.userData.baseOpacity = 1.0;
    captionMeshes.push(capText);
    group.add(capText);
  }

  // === PINNED HEADLINE ===
  const headline = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68,
    color: COLORS.paper,
    align: 'left'
  });
  headline.position.set(-1.6, 1.9, 0);
  group.add(headline);

  // === ACCENT LIGHT ===
  accentLight = new PointLight(COLORS.accent, 1.4, 4);
  accentLight.position.set(COL_X - 0.2, 0, 0.3);
  group.add(accentLight);

  // === UPDATE PLATE VISUALS ===
  function updatePlateVisuals() {
    // Normalize Y to loop range [0, LOOP_H)
    const normY = ((state.columnY % LOOP_H) + LOOP_H) % LOOP_H;

    plateMeshes.forEach((pm, idx) => {
      // World Y position of this plate
      const plateWorldY = -idx * PITCH - normY;
      const distFromCenter = Math.abs(plateWorldY);

      // Focus scale: smooth transition from 1.0 to 1.06
      // Maximum focus when distFromCenter = 0, fades to 1.0 at distance > PITCH
      const focusScale = distFromCenter < PITCH
        ? 1.0 + (1 - distFromCenter / PITCH) * 0.06
        : 1.0;

      pm.scale.set(focusScale, focusScale, 1);

      // Caption opacity fade
      const cap = captionMeshes[idx];
      const capOpacity = Math.max(0, 1 - distFromCenter / (PITCH * 2));

      if (cap && cap.traverse) {
        cap.traverse((child) => {
          if (child.material && 'opacity' in child.material) {
            child.material.opacity = capOpacity;
            child.material.transparent = true;
            child.material.needsUpdate = true;
          }
        });
      }
    });

    // Update accent light to follow nearest focused plate
    const nearestIdx = Math.round((state.columnY / PITCH)) % N_PLATES;
    const nearestPlateY = -nearestIdx * PITCH;
    accentLight.position.y = nearestPlateY;
  }

  // === SCROLL HANDLER ===
  group.userData.handlers = {
    scroll: (evt) => {
      if (state.isSettling) return;

      // Scroll sensitivity: 1.5 units per viewport scroll
      state.columnY += evt.deltaY * 0.0015;

      updatePlateVisuals();

      // Schedule settle-to-grid after scroll stops
      clearTimeout(scrollSettleTimer);
      scrollSettleTimer = setTimeout(() => {
        settleToGrid();
      }, 200);
    }
  };

  function settleToGrid() {
    state.isSettling = true;
    const targetY = Math.round(state.columnY / PITCH) * PITCH;

    const tl = gsap.to(state, {
      columnY: targetY,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      onUpdate: updatePlateVisuals,
      onComplete: () => {
        state.isSettling = false;
      }
    });
    timelines.push(tl);
  }

  // === APPLY FLY-THROUGH PRIMITIVE ===
  if (ctx.primitives && ctx.primitives['fly-through']) {
    const flyRes = ctx.primitives['fly-through'](group, {
      depthUnits: 2.5,
      trigger: 'scroll'
    });
    if (flyRes && flyRes.cleanup) {
      group.userData.flyCleanup = flyRes.cleanup;
    }
  }

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    clearTimeout(scrollSettleTimer);

    if (group.userData.flyCleanup) {
      group.userData.flyCleanup();
    }

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  // Initial state
  updatePlateVisuals();

  return group;
}
